import { DEFAULT_SERVER, type Config } from './types.ts';

export function resolveConfig(
  env: Record<string, string | undefined>,
  overrides: { server?: string; json?: boolean },
): Config {
  const raw = overrides.server ?? env.MUGGE_SERVER ?? DEFAULT_SERVER;
  const server = raw.trim().replace(/\/+$/, '');
  if (!/^https?:\/\/[^\s\/]+/.test(server)) throw new Error(`invalid server url: ${raw}`);
  const json = overrides.json === true || env.MUGGE_JSON === '1' || env.MUGGE_JSON === 'true';
  return { server, json };
}
